# --- 4. decorators = middleware -------------------------------
def retry(fn):
    @functools.wraps(fn)
    def wrapper(*a, **kw):
        for attempt in range(3):
            try:
                return fn(*a, **kw)
            except Exception:
                if attempt == 2: raise
                time.sleep(0.2 * (attempt + 1))
    return wrapper

@retry
def flaky_llm_call():
    if random.random() < 0.7: raise ConnectionError("429")
    return "ok"

# --- 5. generators = streaming --------------------------------
def read_lines(path):
    with open(path) as f:
        for line in f:
            yield line.strip()

for row in read_lines("bigfile.csv"):   # constant memory
